import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const nightmareCard='a2-p15-r2c2';
export const nightmareScenarios=['nightmare-ordinary', 'nightmare-owner-ordinary', 'nightmare-low', 'nightmare-dedicated', 'nightmare-pair', 'nightmare-all', 'nightmare-near', 'nightmare-same-faction', 'nightmare-water', 'nightmare-metal', 'nightmare-lower', 'nightmare-maai-ordinary', 'nightmare-maai-dedicated', 'nightmare-evade-ordinary', 'nightmare-evade-dedicated', 'nightmare-fate', 'nightmare-suppressed', 'nightmare-silenced', 'nightmare-stopped', 'nightmare-wrong-owner', 'nightmare-decline', 'nightmare-noncounter', 'nightmare-reroll', 'nightmare-asfelt-ordinary', 'nightmare-asfelt-dedicated', 'nightmare-recovery-ordinary', 'nightmare-recovery-dedicated', 'nightmare-asfelt-recovery-ordinary', 'nightmare-asfelt-recovery-dedicated', 'nightmare-resist-success-ordinary', 'nightmare-resist-success-dedicated'] as const;
export type NightmareScenario=typeof nightmareScenarios[number];
export function isNightmareScenario(name:string):name is NightmareScenario{return (nightmareScenarios as readonly string[]).includes(name);}
export function nightmareMode(name:NightmareScenario){const suffix=name.replace('nightmare-',''),dedicated=!suffix.includes('ordinary')&&!['low','decline'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',follower=suffix==='water'?'a2-p23-r1c1':suffix==='metal'?'a2-p22-r1c1':suffix==='lower'?'a2-p19-r1c3':null,maai=suffix.startsWith('maai'),evade=suffix.startsWith('evade'),cancel=suffix==='fate',decline=suffix==='decline',reroll=suffix==='reroll',asfelt=suffix.startsWith('asfelt'),recovery=suffix.includes('recovery'),success=suffix.startsWith('resist-success'),targets=suffix==='all'?[1,2,3]:suffix==='pair'?[1,2]:[1];return {suffix,dedicated,owner,follower,maai,evade,cancel,decline,reroll,asfelt,recovery,success,targets};}
export function makeNightmarePhysical(name:NightmareScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=nightmareMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'魔聖母ディア':'侍大将のシン',m.asfelt?'竜皇子アスフェルト':'黒騎士ガーウィン',m.suffix==='same-faction'?'魔導王ガイナス':'小人のランバ','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?6:12)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.magic_level!+=(options.warrior??(m.suffix==='low'?5:m.dedicated?0:6))-gameStats(s,a).magic_level;
 const keep=[takeCard(s,a,nightmareCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3'),takeCard(s,d,'a2-p02-r1c3')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.maai)keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.evade)keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`NIGHTMARE_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('NIGHTMARE_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('NIGHTMARE_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('NIGHTMARE_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('NIGHTMARE_FIXTURE_COUNTER_LIMIT');}
 if(m.suffix==='near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
